//! Running one test: load the target, check requirements, run, clean up.

use std::panic::AssertUnwindSafe;

use futures::FutureExt;

use crate::context::Context;
use crate::error::Result;
use crate::target::{Capability, Target};

/// Identity of a test, generated by `#[testkit::test]`.
#[derive(Clone, Copy, Debug)]
pub struct TestInfo {
    /// The stable test ID.
    pub id: &'static str,
    /// The function name, which is also the nextest test name.
    pub name: &'static str,
    pub description: &'static str,
    pub requires: &'static [Capability],
}

/// Run a test body against the target named by `OPENSHELL_TEST_TARGET`.
///
/// Cleanup runs whether the body passes, fails, or panics. The test fails if
/// the body fails, or if cleanup fails after the body passed.
///
/// # Panics
///
/// Panics to fail the test.
pub async fn run<F>(info: TestInfo, body: F)
where
    F: AsyncFnOnce(&mut Context) -> Result,
{
    let name = info.name;
    eprintln!("[{name}] {} ({})", info.description, info.id);

    let target = Target::from_env().unwrap_or_else(|error| panic!("[{name}] {error}"));
    let missing = missing_requirements(&info, &target);
    // Whoever selects tests must exclude those the target can't support.
    // Reaching here means they didn't, so fail rather than report a pass for
    // an untested behavior.
    assert!(
        missing.is_empty(),
        "[{name}] requires {}, which the target does not provide",
        missing.join(", ")
    );

    let client = target
        .connect()
        .await
        .unwrap_or_else(|error| panic!("[{name}] {error}"));
    let mut cx = Context::new(&client, &target.workspace, target.cli());
    eprintln!("[{name}] run id {}", cx.run_id());

    let outcome = AssertUnwindSafe(body(&mut cx)).catch_unwind().await;
    let cleanup_failures = cx.cleanup().await;
    for failure in &cleanup_failures {
        eprintln!("[{name}] cleanup failed: {failure}");
    }

    match outcome {
        Err(panic) => std::panic::resume_unwind(panic),
        Ok(Err(error)) => panic!("[{name}] {error}"),
        Ok(Ok(())) => assert!(
            cleanup_failures.is_empty(),
            "[{name}] passed, but cleanup failed: {}",
            cleanup_failures.join("; ")
        ),
    }
}

fn missing_requirements(info: &TestInfo, target: &Target) -> Vec<&'static str> {
    info.requires
        .iter()
        .filter(|capability| !target.capabilities.provides(**capability))
        .map(|capability| capability.name())
        .collect()
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use super::*;

    #[test]
    fn reports_missing_requirements() {
        let target = Target::parse(
            "gateway:\n  endpoint: http://x\ncapabilities:\n  gpu: true\n",
            PathBuf::new(),
        )
        .unwrap();
        let info = TestInfo {
            id: "t-00000000",
            name: "t",
            description: "d",
            requires: &[Capability::Gpu, Capability::ServiceExposure],
        };
        assert_eq!(missing_requirements(&info, &target), ["service_exposure"]);
    }
}
